import{readFileSync,writeFileSync,existsSync}from'node:fs';import{createHash}from'node:crypto';import{execFileSync}from'node:child_process';
const root='artifacts/completion-v074',output=root+'/raw-evidence-commit-check.json';if(existsSync(output))throw Error('Preserve prior byte audit');
const indexPath=root+'/evidence-final-inventory.json',inventory=JSON.parse(readFileSync(indexPath)),rows=[],hash=b=>createHash('sha256').update(b).digest('hex');
for(const f of [...inventory.files,{path:indexPath,sha256:hash(readFileSync(indexPath)),gitIgnored:false}]){if(f.gitIgnored)continue;let committed;try{committed=hash(execFileSync('git',['-c','core.longpaths=true','cat-file','blob','HEAD:'+f.path],{windowsHide:true,maxBuffer:64*1024*1024}));}catch(e){throw Error('Cannot read committed blob: '+f.path,{cause:e});}const current=hash(readFileSync(f.path));rows.push({path:f.path,sha256:f.sha256,current,committed,equal:current===f.sha256&&committed===f.sha256});}
const checkerSource=readFileSync(new URL(import.meta.url),'utf8');
const report={at:new Date().toISOString(),revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8',windowsHide:true}).trim(),sourceRevision:inventory.sourceRevision,method:'Byte-for-byte current and actual committed Git blobs against final evidence inventory. Per-command core.longpaths=true and cat-file blob avoid Windows path/stat ambiguity. Original CRLF/raw JSON are protected by -text attributes; no evidence normalization.',firstAttempt:{status:'failed',nodeExitCode:1,gitExitCode:128,command:'git show HEAD:<path>',failedPath:'artifacts/completion-v074/browser/full-1/output/g0-VIS-04-and-RUN-11-foot--ef783-nd-walkable-foreground-fade-chrome/attachments/foreground-fades-and-player-remains-readable-b5970bbf3c411b97b8dc4e57eaa00ed2fb519473.png',stderr:'fatal: failed to stat HEAD:<path>: Filename too long',finding:'Windows Git show path/stat resolution failed; this was not proof of a missing blob. No source, report or archive was changed before this corrected read-only audit.'},checkerSource,checkerSourceSha256:hash(checkerSource),filesChecked:rows.length,mismatches:rows.filter(r=>!r.equal),allChecksPassed:rows.every(r=>r.equal),ignoredLocalFilesNotClaimedAsGitArchived:inventory.retainedLocalIgnoredFiles,scope:'This additive post-inventory audit records its actual corrected source and the earlier tool failure; its own output is intentionally outside its own recursive hash set.',rows};
writeFileSync(output,JSON.stringify(report,null,2));console.log(JSON.stringify({filesChecked:report.filesChecked,mismatches:report.mismatches.length,pass:report.allChecksPassed}));if(!report.allChecksPassed)process.exitCode=1;
